import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"隐私政策","description":"Clash 不收集 App 或 VPN 数据。了解配置、凭据、日志、诊断、iCloud 备份及用户主动指定的网络请求如何处理。","frontmatter":{"title":"隐私政策","description":"Clash 不收集 App 或 VPN 数据。了解配置、凭据、日志、诊断、iCloud 备份及用户主动指定的网络请求如何处理。","keywords":["Clash隐私政策","Clash VPN数据","iOS代理数据收集","VPN隐私政策","本地配置隐私"],"jsonLd":{"@context":"https://schema.org","@type":"WebPage","name":"Clash 隐私政策","description":"Clash 不收集 App 或 VPN 数据，并说明本地配置、诊断和用户主动指定请求的处理方式。","url":"https://clash.md/zh/privacy","inLanguage":"zh-CN","about":["VPN 数据","本地配置","诊断信息","iCloud 备份"],"publisher":{"@type":"Organization","name":"OmniWide Media Limited","email":"legal@omniwide.media"}}},"headers":[],"relativePath":"zh/privacy.md","filePath":"zh/privacy.md","lastUpdated":1785318168000}`),a={name:`zh/privacy.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to “隐私政策”">​</a></h1><p><strong>最后更新：2026 年 7 月 29 日</strong></p><p>Clash 是运行在你设备上的网络工具。它不是代理服务，只会连接到<strong>你</strong> 配置的服务，背后没有开发者运营的中转服务器。</p><p>Clash 的发行主体及本政策中的“我们”是指 <strong>OmniWide Media Limited</strong>。</p><h2 id="我们收集什么" tabindex="-1">我们收集什么 <a class="header-anchor" href="#我们收集什么" aria-label="Permalink to “我们收集什么”">​</a></h2><p>不收集任何数据。</p><p>Clash 没有账户系统、分析、遥测、广告 SDK、追踪 SDK、第三方崩溃报告器或自动诊断上传器。App 的隐私清单声明不收集任何数据类型、不进行追踪，也没有追踪域名。</p><p>按照 Apple 对 App 隐私的定义，只在设备上处理的信息不属于“收集”。我们不会把 App 数据或 VPN 数据发送给自己，也不会发送给分析、广告或数据经纪合作方。</p><h2 id="vpn-数据承诺" tabindex="-1">VPN 数据承诺 <a class="header-anchor" href="#vpn-数据承诺" aria-label="Permalink to “VPN 数据承诺”">​</a></h2><p>我们不收集或出售用户数据，不将其用于自身目的，也不向第三方披露。 Clash 只会在设备上处理提供你所请求功能所必需的网络流量。</p><p>由你配置的代理、DNS、订阅、Provider 与测试服务属于用户主动指定的外部服务；它们不是我们运营的服务，也不是由我们选择的数据接收方。</p><h2 id="留在设备上的内容" tabindex="-1">留在设备上的内容 <a class="header-anchor" href="#留在设备上的内容" aria-label="Permalink to “留在设备上的内容”">​</a></h2><ul><li><strong>配置文件</strong>会按照你提供的内容逐字节保存，包括文件内含的凭据。文件受 iOS 数据保护与 App 容器保护。</li><li><strong>App 设置</strong>保存在 App 容器内；本地代理共享凭据等敏感设置保存在设备钥匙串中。</li><li><strong>连接与请求活动</strong>是 App 显示的有限运行信息。实时与近期连接数据有数量上限，只在本机保存，不会由 Clash 上传。Clash 不记录网络流量正文。</li><li><strong>日志与诊断</strong>留在本机。Clash 可以在设备上接收经 Apple 隐私过滤的 MetricKit 诊断，但没有自动上传器。只有在你明确使用导出或共享操作时，数据才会离开设备，接收方也由你选择。</li></ul><h2 id="用户主动指定的网络连接" tabindex="-1">用户主动指定的网络连接 <a class="header-anchor" href="#用户主动指定的网络连接" aria-label="Permalink to “用户主动指定的网络连接”">​</a></h2><p>Clash 会为你配置或主动启动的功能建立网络连接：</p><ul><li><strong>配置中指定的订阅、规则 Provider、代理 Provider、代理与 DNS 服务。</strong> 根据服务类型，它们可能收到你的 IP 地址、请求时间、认证信息、DNS 查询、流量元数据，以及所选协议能够访问的内容。</li><li><strong>资源更新。</strong> 更新来源会显示在 App 的“资源”页面；默认地理数据库来源指向 GitHub 上 MetaCubeX 的 <code>meta-rules-dat</code> Release。</li><li><strong>你主动启动的诊断。</strong> 网络质量测试会连接 Apple 的测量端点；STUN 测试连接你输入的服务器；延迟测试连接所选策略组配置的 URL。</li><li><strong>已配置的后台更新。</strong> 启用后，Clash 可在后台检查你配置的订阅与资源，且仅用于你选择的更新目的。</li></ul><p>这些外部服务适用其各自的条款与隐私政策。我们不控制它们，也不会收到它们处理的数据。</p><p>Clash 不会为了开发者自身利益在后台联系任何服务。订阅与资源的自动更新只会在你配置或启用后运行。</p><h2 id="icloud-备份" tabindex="-1">iCloud 备份 <a class="header-anchor" href="#icloud-备份" aria-label="Permalink to “iCloud 备份”">​</a></h2><p>如果你明确创建 iCloud 备份，备份会按照 Apple 的条款保存在<strong>你的</strong> iCloud 账户中。我们无法访问这些备份。</p><h2 id="保留、删除与隐私选择" tabindex="-1">保留、删除与隐私选择 <a class="header-anchor" href="#保留、删除与隐私选择" aria-label="Permalink to “保留、删除与隐私选择”">​</a></h2><p>我们不收集数据，也不提供账户，因此没有服务器端用户档案或由开发者持有的个人数据需要保留或删除。</p><ul><li>本机配置、设置、凭据、日志与诊断会保留在设备上，直到你删除对应项目、使用“清除全部本机数据”或卸载 Clash。</li><li>“清除全部本机数据”会删除本机配置、设置与钥匙串凭据，但不会删除 iCloud 备份。</li><li>当前 iCloud 备份可在 Clash 的“备份与恢复”页面中左滑备份并选择“删除”。</li><li>你可以通过断开连接、移除配置、关闭已配置的更新，或不运行、不导出诊断来停止相应的数据处理。</li></ul><h2 id="儿童" tabindex="-1">儿童 <a class="header-anchor" href="#儿童" aria-label="Permalink to “儿童”">​</a></h2><p>Clash 是通用网络工具，并非面向儿童。我们不会有意收集任何人的个人数据，包括儿童的数据。</p><h2 id="政策变更" tabindex="-1">政策变更 <a class="header-anchor" href="#政策变更" aria-label="Permalink to “政策变更”">​</a></h2><p>当 App 或数据处理方式发生变化时，我们可能更新本政策。当前版本及更新日期会发布在本网址；重大变更也会在 App 或版本信息中说明。</p><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to “联系方式”">​</a></h2><p>如需就本隐私政策或任何隐私相关事项联系我们，请发送电子邮件至 <a href="mailto:legal@omniwide.media" target="_blank" rel="noreferrer">legal@omniwide.media</a>，或邮寄至： <strong>OmniWide Media Limited, 128 City Road, London, United Kingdom, EC1V 2NX</strong>。</p><p>非保密问题可以提交到 <a href="https://github.com/TokenPLS/Hako-Client/issues" target="_blank" rel="noreferrer">Clash 客户端 Issue</a>。请勿在公开 Issue 中发布订阅地址、凭据、服务器地址、私密日志或其他敏感信息。</p>`,30)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};